/// Shell shared by both sheets: surface, top radius, handle, safe area.
/// Stretched column so the CTA fills the width; children centre themselves.
class _Sheet extends StatelessWidget {
  const _Sheet({required this.children});

  final List<Widget> children;

  @override
  Widget build(BuildContext context) {
    final scheme = Theme.of(context).colorScheme;

    return DecoratedBox(
      decoration: BoxDecoration(
        color: scheme.surface,
        borderRadius: AppTokens.radiusSheet,
      ),
      child: Padding(
        padding: const EdgeInsets.all(AppTokens.sideMargin),
        child: SafeArea(
          top: false,
          child: Column(
            mainAxisSize: .min,
            crossAxisAlignment: .stretch,
            children: [
              const Center(child: _Handle()),
              const SizedBox(height: AppTokens.space3),
              ...children,
            ],
          ),
        ),
      ),
    );
  }
}

/// Decorative drag handle: the sheet closes through its CTA, not by
/// dragging, because a dismissed sheet would need a state the notifier
/// does not have.
class _Handle extends StatelessWidget {
  const _Handle();

  @override
  Widget build(BuildContext context) {
    final colors = Theme.of(context).extension<AppColors>()!;

    return SizedBox(
      width: AppTokens.sheetHandleWidth,
      height: AppTokens.sheetHandleHeight,
      child: DecoratedBox(
        decoration: BoxDecoration(
          color: colors.track,
          borderRadius: AppTokens.radiusProgress,
        ),
      ),
    );
  }
}
